"use strict";(self.webpackChunkdatabricks_monolith=self.webpackChunkdatabricks_monolith||[]).push([[89587],{389587:e=>{e.exports="# ============================================================================\n# Migration IR Schema v0 — Thin Decision Manifest\n# ============================================================================\n#\n# This file defines the schema for migration-plan.yml, the intermediate\n# representation between the Research and Generate phases of the ETL→SDP\n# migration tool.\n#\n# Source-pluggable: works for DBT today, plus future ETL sources (Snowflake,\n# Informatica, etc.) by setting metadata.source_type and using free-form\n# source-specific fields under nodes[].source_meta.\n#\n# DESIGN PRINCIPLES:\n#\n#   1. Decisions, not translations.\n#      The IR captures WHAT each artifact should become, not HOW to write it.\n#      The generate phase reads the original source file for content.\n#\n#   2. Every field earns its place.\n#      If the generate phase can derive it from the source file,\n#      it does NOT belong in the IR. Fields exist only when:\n#      - The information cannot be derived (source catalog mappings)\n#      - The information is a judgment call (sdp_type classification)\n#      - The information is needed by the orchestrator (dag_levels)\n#\n#   3. Flat over nested. Scannable in 30 seconds.\n#      A user reviewing this file should immediately see:\n#      what each artifact becomes, which sources map where, what needs attention.\n#\n#   4. `notes` and `source_meta` are the escape hatches.\n#      `notes` is free-text guidance from research→generate.\n#      `source_meta` is free-form structured data the source pack uses for\n#      anything that doesn't fit standard fields.\n#\n#   5. Omit, don't default.\n#      Optional fields are omitted entirely when not needed, not set to null\n#      or empty. A 5-node project with no issues should be ~30 lines.\n#\n# CONSUMERS:\n#\n#   Orchestrator  — reads metadata, dag_levels, summary\n#   Generate phase — reads nodes[].sdp_type + sources[] + node.source_path,\n#                    then reads the original source file for content\n#   Repair phase  — reads everything; can propose amendments to any field\n#   User          — reviews decisions, source mappings, flags\n#\n# ============================================================================\n\n# --- Required ---\n\nversion: 0\n\nmetadata:\n  # Source identity\n  source_type: 'dbt' # dbt | snowflake | informatica | ... — determines which source pack the generate/repair phases load\n  source_project_name: 'my_analytics' # human-readable project name\n  source_project_path: './my_dbt_project' # root of the source project (relative or absolute)\n\n  # Generation defaults — per-node overrides are possible\n  output_format: 'sql' # sql | python\n\n  # Pipeline display name\n  pipeline_name: 'migrated_my_analytics'\n\n  # Catalog/schema are NOT in the IR. The migration writes SDP files to the pipeline,\n  # and the pipeline's existing catalog/schema apply. If the user wants a different\n  # target, they configure it via editPipelineSettings (which surfaces an approval\n  # card where they review and confirm).\n\n# --- Source Mappings (Required) ---\n#\n# WHY THIS EXISTS: The generate phase cannot guess catalog.schema.table names.\n# Source-side abstractions (DBT source('s','t'), Snowflake external tables,\n# Informatica source connections) need to resolve to concrete UC locations\n# that only the user/research phase knows.\n#\n# HOW IT'S USED: When the generate phase encounters a source reference in the\n# original file, it looks up the mapping here and writes the resolved name.\n#\n# Intra-project references (DBT ref(), Snowflake same-schema references, etc.)\n# do NOT need mappings — SDP resolves them within the pipeline. Only EXTERNAL\n# sources need explicit resolution.\n#\n# The `source` field is source-flavored — DBT uses {name, table}; other\n# sources may use a string identifier or a different shape.\n\nsources:\n  - source: { name: 'raw', table: 'orders' } # DBT-flavored example\n    catalog_table: 'raw_catalog.raw_schema.orders'\n\n  - source: { name: 'raw', table: 'users' }\n    catalog_table: 'raw_catalog.raw_schema.users'\n\n  - source: { name: 'events', table: 'clickstream' }\n    catalog_table: 'events_catalog.streaming.clickstream'\n\n# --- Node Decisions (Required) ---\n#\n# One entry per source artifact (DBT model/snapshot/seed, Snowflake DDL/task,\n# Informatica mapping, etc.). This is the core of the IR.\n#\n# REQUIRED FIELDS per node:\n#   id           — unique identifier (typically the source artifact name)\n#   source_path  — path to the original source file (generate phase reads this)\n#   sdp_type     — THE classification decision\n#\n# OPTIONAL FIELDS (omit when not needed):\n#   output_format    — override metadata.output_format for this node\n#   sdp_cdc_hint     — only for auto_cdc / auto_cdc_snapshot nodes\n#   confidence       — only include for medium/low (high is the default assumption)\n#   notes            — free-text guidance for the generate phase\n#   source_meta      — free-form object for source-pack-specific data the\n#                      generate phase needs that doesn't fit standard fields\n#   manual_review    — list of issues requiring human attention before/after generation\n#   skip             — set to true to exclude from generation (user decided not to migrate)\n#\n# sdp_type values:\n#   streaming_table    — append-only incremental (CREATE OR REFRESH STREAMING TABLE)\n#   materialized_view  — full recompute batch (CREATE OR REFRESH MATERIALIZED VIEW)\n#   temporary_view     — intermediate, not persisted (CREATE TEMPORARY VIEW)\n#   auto_cdc           — change data capture with SCD (AUTO CDC INTO)\n#   auto_cdc_snapshot  — CDC from periodic snapshots (create_auto_cdc_from_snapshot_flow)\n\nnodes:\n  # --- Simple: straightforward mapping, no extras needed ---\n\n  - id: stg_orders\n    source_path: models/staging/stg_orders.sql\n    sdp_type: streaming_table\n\n  - id: stg_customers\n    source_path: models/staging/stg_customers.sql\n    sdp_type: streaming_table\n\n  - id: stg_products\n    source_path: models/staging/stg_products.sql\n    sdp_type: materialized_view\n    notes: 'Batch source, full reload each run — no incremental strategy in DBT'\n\n  # --- Intermediate: internal-only, not persisted ---\n\n  - id: int_order_items\n    source_path: models/intermediate/int_order_items.sql\n    sdp_type: temporary_view\n\n  # --- Mart: final consumption layer ---\n\n  - id: fct_daily_revenue\n    source_path: models/marts/fct_daily_revenue.sql\n    sdp_type: materialized_view\n\n  - id: dim_customers\n    source_path: models/marts/dim_customers.sql\n    sdp_type: materialized_view\n\n  # --- CDC: incremental with merge → AUTO CDC ---\n\n  - id: orders_merged\n    source_path: models/intermediate/orders_merged.sql\n    sdp_type: auto_cdc\n    sdp_cdc_hint:\n      scd_type: 1 # 1 = current state (upsert), 2 = history tracking\n    notes: >\n      DBT uses incremental_strategy='merge' with unique_key='order_id'.\n      updated_at column available for sequence_by.\n\n  # --- Snapshot → AUTO CDC SCD Type 2 ---\n\n  - id: users_snapshot\n    source_path: snapshots/users_snapshot.sql\n    sdp_type: auto_cdc\n    sdp_cdc_hint:\n      scd_type: 2\n    notes: 'DBT timestamp strategy, updated_at as the tracking column'\n\n  # --- Snapshot with check strategy → AUTO CDC from snapshot ---\n\n  - id: products_snapshot\n    source_path: snapshots/products_snapshot.sql\n    sdp_type: auto_cdc_snapshot\n    sdp_cdc_hint:\n      scd_type: 2\n    notes: \"DBT check strategy (check_cols='all') — no timestamp column available\"\n\n  # --- Complex: needs Python, lower confidence ---\n\n  - id: complex_model\n    source_path: models/intermediate/complex_model.sql\n    sdp_type: auto_cdc\n    output_format: python # override: complex Jinja needs Python\n    sdp_cdc_hint:\n      scd_type: 1\n    confidence: medium\n    notes: >\n      Uses custom_pivot macro — expand inline as .groupBy().pivot().\n      Uses dbt_utils.surrogate_key — convert to sha2(concat_ws('|', ...)).\n    manual_review:\n      - 'custom_pivot macro has no direct SDP equivalent — verify expanded logic'\n\n  # --- Seed: CSV file → materialized view reading from Volume ---\n\n  - id: seed_countries\n    source_path: seeds/countries.csv\n    sdp_type: materialized_view\n    seed_volume_path: '/Volumes/analytics_catalog/analytics/seeds/countries.csv'\n    notes: 'Upload CSV to Volume before running pipeline'\n\n  # --- Skipped: user decided not to migrate this one ---\n\n  - id: legacy_report\n    source_path: models/legacy/legacy_report.sql\n    sdp_type: materialized_view\n    skip: true\n    notes: 'Deprecated model — user chose to skip migration'\n\n# --- DAG Levels (Required) ---\n#\n# Topological ordering of nodes for parallel generation.\n# Nodes within the same level have no dependencies on each other\n# and can be generated concurrently.\n#\n# The orchestrator uses this to batch generation when parallelizing.\n# The generate phase does NOT use this — it reads refs from the source file.\n\ndag_levels:\n  - [stg_orders, stg_customers, stg_products, seed_countries]\n  - [int_order_items, users_snapshot, products_snapshot]\n  - [orders_merged, dim_customers, complex_model]\n  - [fct_daily_revenue]\n\n# --- Summary (Required) ---\n#\n# Quick stats for the orchestrator to present to the user.\n# The user should be able to approve/reject the migration from this alone.\n\nsummary:\n  total_nodes: 12\n  skipped: 1\n  by_sdp_type:\n    streaming_table: 2\n    materialized_view: 4\n    temporary_view: 1\n    auto_cdc: 3\n    auto_cdc_snapshot: 1\n  needs_manual_review: 1\n  # Highlight anything the user should pay attention to\n  alerts:\n    - '1 node (complex_model) has medium confidence — review notes before generating'\n    - '1 node (legacy_report) marked as skip'\n    - '1 seed file (countries.csv) must be uploaded to Volume before pipeline runs'\n\n# ============================================================================\n# SCHEMA FIELD REFERENCE (for agent implementers)\n# ============================================================================\n#\n# metadata (required):\n#   source_type         enum      \"dbt\" | \"snowflake\" | \"informatica\" | ...\n#                                 Determines which references/sources/<x>/ pack the\n#                                 generate and repair phases load.\n#   source_project_name string    Source project name (e.g. from dbt_project.yml)\n#   source_project_path string    Path to source project root\n#   output_format       string    \"sql\" | \"python\" — default for all nodes\n#   pipeline_name       string    Display name for the SDP pipeline\n#\n#   Catalog/schema are NOT IR fields. The migration writes SDP files into the\n#   pipeline, and the pipeline's existing catalog/schema apply at runtime.\n#   To target a different catalog/schema, the agent calls editPipelineSettings,\n#   which surfaces an approval card the user confirms.\n#\n# sources[] (required, at least one):\n#   source              object    Source-flavored identifier. Shape depends on\n#                                 source_type — DBT uses {name, table}; other\n#                                 sources may use a string identifier or different keys.\n#   catalog_table       string    Fully qualified Unity Catalog table\n#\n# nodes[] (required, at least one):\n#   id                  string    REQUIRED — unique node identifier\n#   source_path         string    REQUIRED — path to source file relative to project root\n#   sdp_type            enum      REQUIRED — streaming_table | materialized_view |\n#                                            temporary_view | auto_cdc | auto_cdc_snapshot\n#   output_format       string    OPTIONAL — override metadata.output_format\n#   sdp_cdc_hint        object    OPTIONAL — only for auto_cdc / auto_cdc_snapshot\n#     scd_type          int         REQUIRED within hint — 1 (current) or 2 (history)\n#   seed_volume_path    string    OPTIONAL — only for reference-data nodes, path in Volume\n#   confidence          string    OPTIONAL — \"medium\" | \"low\" (omit = high)\n#   notes               string    OPTIONAL — free-text guidance for generate phase\n#   source_meta         object    OPTIONAL — free-form, source-pack-specific structured data\n#   manual_review       string[]  OPTIONAL — issues needing human attention\n#   skip                bool      OPTIONAL — true to exclude from generation\n#\n# dag_levels (required):\n#   list of lists of node IDs, topologically ordered\n#\n# summary (required):\n#   total_nodes         int       Total node count (including skipped)\n#   skipped             int       Count of skip: true nodes\n#   by_sdp_type         map       Count per sdp_type\n#   needs_manual_review int       Count of nodes with manual_review\n#   alerts              string[]  Human-readable warnings for user review\n#\n# ============================================================================\n# REPAIR PHASE: AMENDABLE FIELDS\n# ============================================================================\n#\n# The repair phase can propose amendments to ANY field. Common amendments:\n#\n#   node.sdp_type           — reclassify (e.g., streaming_table → auto_cdc)\n#   node.sdp_cdc_hint       — add/change SCD type\n#   node.output_format      — switch sql ↔ python\n#   node.notes              — add guidance that was missing\n#   node.source_meta        — refine source-pack-specific data\n#   node.skip               — skip a node that can't be migrated\n#   sources[].catalog_table — fix wrong catalog.schema.table mapping\n#\n# Amendment format:\n#\n#   ir_amendments:\n#     - node_id: \"stg_orders\"\n#       field: \"sdp_type\"\n#       new_value: \"auto_cdc\"\n#       reason: \"Source has UPDATEs — streaming_table can't handle them\"\n#     - node_id: \"stg_orders\"\n#       field: \"sdp_cdc_hint\"\n#       new_value: { scd_type: 1 }\n#       reason: \"Added CDC hint for the reclassified node\"\n#     - source: { name: \"raw\", table: \"orders\" }\n#       field: \"catalog_table\"\n#       new_value: \"prod_catalog.raw_schema.orders\"\n#       reason: \"Table not found in dev_catalog — correct catalog is prod_catalog\"\n#\n# ============================================================================\n# WHAT'S INTENTIONALLY NOT IN THE IR\n# ============================================================================\n#\n# compiled_sql        — generate phase reads source file and transpiles\n# expectations[]      — generate phase reads source-side test definitions directly\n# dependencies[]      — generate phase reads refs from source file\n# macros_used[]       — generate phase discovers templating helpers when reading\n# column_list         — generate phase reads from source file / source schema\n# cluster_config      — pipeline settings handle this (serverless by default)\n# schedule            — pipeline settings handle this\n# templating_complexity — output_format: python IS the actionable decision\n# downstream[]        — not needed; dag_levels captures the ordering\n# source_materialization — generate phase reads this from the source file\n#\n# These fields were considered and rejected because the generate phase can\n# derive them from the source file. Adding them would make the IR a\n# transpilation cache, which defeats the purpose of LLM-driven generation.\n#\n# ============================================================================\n# VERSIONING\n# ============================================================================\n#\n# The `version: 0` field at the top allows future schema evolution.\n# When the schema changes:\n#   - Bump version number\n#   - Research phase produces the new version\n#   - Generate phase checks version and adapts\n#   - Old IRs can be migrated or re-researched\n#\n# Anticipated v1 additions (if patterns emerge from v0 usage):\n#   - source[].source_kind: \"table\" | \"files\" | \"stream\" (for Auto Loader / Kafka)\n#   - node.pipeline_assignment: for multi-pipeline splitting\n#   - node.variables: explicit source-var → SDP param mappings per node\n#   - metadata.variables: global variable mappings\n#\n# ============================================================================\n"}}]);
